export function icon(name, size = 20) {
  const span = document.createElement("span");
  span.className = "icon";
  span.style.display = "inline-grid";
  span.setAttribute("aria-hidden", "true");
  span.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${PATHS[name] ?? PATHS.alert}</svg>`;
  return span;
}
